def para(text='',style=None,align=None,bold=None,after=0):
    p=doc.add_paragraph(text,style=style)
    p.paragraph_format.space_after=Pt(after)
    if align is not None:p.alignment=align;p.paragraph_format.first_line_indent=Cm(0)
    if bold is not None:
        for r in p.runs:r.bold=bold
    return p

def major(t):
    p=para(t,'Heading 1',WD_ALIGN_PARAGRAPH.CENTER)
    return p

def sub(t):return para(t,'Heading 2')

def bullet(t):
    p=para('- '+t);p.paragraph_format.first_line_indent=Cm(0);p.paragraph_format.left_indent=Cm(1.5)
    return p

def figure(path,caption,maxwidth=16.8,maxheight=11.5):
    from PIL import Image
    path=Path(path)
    if not path.exists():return
    w,h=Image.open(path).size
    width=min(maxwidth,maxheight*w/h)
    p=para('',align=WD_ALIGN_PARAGRAPH.CENTER)
    p.paragraph_format.keep_with_next=True;p.paragraph_format.line_spacing=1
    run=p.add_run();run.add_picture(str(path),width=Cm(width))
    for d in p._p.xpath('.//wp:docPr'):d.set('descr',caption)
    p=para(caption,align=WD_ALIGN_PARAGRAPH.CENTER,after=8)
    p.paragraph_format.line_spacing=1.5
    for r in p.runs:r.font.size=Pt(14)

def table(headers,rows,widths,caption):
    p=para(caption,after=4);p.paragraph_format.first_line_indent=Cm(0);p.paragraph_format.keep_with_next=True
    t=doc.add_table(rows=1,cols=len(headers));t.autofit=False;t.alignment=WD_TABLE_ALIGNMENT.CENTER
    for c,w in zip(t.columns,widths):c.width=Cm(w)
    for c,h,w in zip(t.rows[0].cells,headers,widths):c.text=h;c.width=Cm(w)
    for row in rows:
        for c,v,w in zip(t.add_row().cells,row,widths):c.text=str(v);c.width=Cm(w)
    for i,row in enumerate(t.rows):
        trpr=row._tr.get_or_add_trPr()
        if i==0:
            repeat=OxmlElement('w:tblHeader');trpr.append(repeat)
        cant=OxmlElement('w:cantSplit');trpr.append(cant)
        for c in row.cells:
            c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            pr=c._tc.get_or_add_tcPr();mar=OxmlElement('w:tcMar')
            for side in ('top','left','bottom','right'):
                x=OxmlElement('w:'+side);x.set(qn('w:w'),'90');x.set(qn('w:type'),'dxa');mar.append(x)
            pr.append(mar)
            borders=OxmlElement('w:tcBorders')
            for side in ('top','left','bottom','right'):
                x=OxmlElement('w:'+side);x.set(qn('w:val'),'single');x.set(qn('w:sz'),'4');x.set(qn('w:color'),'000000');borders.append(x)
            pr.append(borders)
            if i==0:
                shade=OxmlElement('w:shd');shade.set(qn('w:fill'),'EDEDED');pr.append(shade)
            for p in c.paragraphs:
                p.paragraph_format.keep_with_next=i<len(t.rows)-1
                p.paragraph_format.first_line_indent=Cm(0);p.paragraph_format.line_spacing=1.5
                p.paragraph_format.space_before=Pt(2);p.paragraph_format.space_after=Pt(2)
                p.alignment=WD_ALIGN_PARAGRAPH.LEFT
                for r in p.runs:r.font.size=Pt(14);r.bold=i==0
    para('')

def code(text):
    doc.paragraphs[-1].paragraph_format.keep_with_next=True
    lines=text.strip('\n').splitlines()
    for i,line in enumerate(lines):
        p=para(line.rstrip())
        p.paragraph_format.first_line_indent=Cm(0);p.paragraph_format.line_spacing=1
        p.paragraph_format.keep_with_next=i<len(lines)-1
        p.paragraph_format.widow_control=False
        for r in p.runs:r.font.size=Pt(12)
    para('')

def fragment(path,start,end):
    s=(ROOT/path).read_text();a=s.index(start);b=s.index(end,a)
    s=s[a:b].rstrip();return '\n'.join(x[4:] if x.startswith('    ') else x for x in s.splitlines())

